// Adaptador do Trigger (uso real: chamado via toolWorkflow pelo supervisor, T12).
// Aceita leitura como objeto ou string JSON (o parse é feito em "Validar Entrada").
const t = $('Trigger').first().json;
return [{ json: { leitura_bruta: t.leitura, pergunta_bruta: t.pergunta, via_webhook: false, t0: Date.now() } }];

// Adaptador do Webhook de TESTE: POST { "leitura": {...}, "pergunta": "..." }.
// Mesmo caminho do Trigger daqui em diante (flag via_webhook, ver armadilha 16 do catálogo).
const w = $('Webhook Teste').first().json;
const body = (w.body && typeof w.body === 'object' && !Array.isArray(w.body)) ? w.body : {};
return [{ json: { leitura_bruta: body.leitura, pergunta_bruta: body.pergunta, via_webhook: true, t0: Date.now() } }];

// Valida a entrada ANTES de qualquer chamada ao LLM (não gasta token com entrada inválida).
// Aceita "leitura" como objeto OU como string JSON (o toolWorkflow do supervisor no T12
// pode entregar string). Área fixa por variante do workflow (marcador do build).
const AREA = 'energia';
const ORDEM = ['NORMAL', 'ATENCAO', 'CRITICO'];
const e = $input.first().json;

let leitura = e.leitura_bruta;
const erros = [];
if (typeof leitura === 'string') {
  try { leitura = JSON.parse(leitura); } catch (x) { erros.push('leitura não é JSON válido: ' + x.message); leitura = null; }
}
if (!erros.length) {
  if (!leitura || typeof leitura !== 'object' || Array.isArray(leitura)) {
    erros.push('leitura ausente ou não é um objeto');
  } else {
    if (typeof leitura.id_maquina !== 'string' || !leitura.id_maquina) erros.push('leitura.id_maquina ausente');
    if (!leitura.valores || typeof leitura.valores !== 'object' || Array.isArray(leitura.valores)) erros.push('leitura.valores ausente');
    const g = leitura.guardrail;
    if (!g || typeof g !== 'object' || !g.por_especialista || !ORDEM.includes(g.por_especialista[AREA])) {
      erros.push('leitura.guardrail.por_especialista.' + AREA + ' ausente ou inválido');
    }
  }
}

let pergunta = null;
if (typeof e.pergunta_bruta === 'string' && e.pergunta_bruta.trim()) pergunta = e.pergunta_bruta.trim().slice(0, 500);

if (erros.length) {
  return [{ json: { ok: false, area: AREA, erro: 'Entrada inválida: ' + erros.join('; '), via_webhook: !!e.via_webhook, t0: e.t0 } }];
}

const prompt_usuario =
  (pergunta ? 'PERGUNTA DO SUPERVISOR: ' + pergunta + '\n\n' : '') +
  'LEITURA:\n' + JSON.stringify(leitura) +
  '\n\nENTREGA: ao terminar, chame a ferramenta format_final_json_response com o argumento {"output": <parecer JSON>} (o parecer vai DENTRO da chave "output").';

return [{ json: { ok: true, area: AREA, leitura, pergunta, prompt_usuario, via_webhook: !!e.via_webhook, t0: e.t0 } }];

