      "additionalProperties": false,
      "properties": {
        "grandeza": {
          "type": "string"
        },
        "janela_min": {
          "type": "number"
        },
        "media": {
          "type": [
            "number",
            "null"
          ]
        },
        "desvio_padrao": {
          "type": [
            "number",
            "null"
          ]
        },
