parameters.jsCode:
// Pós-processamento DETERMINÍSTICO (o LLM opina, o n8n garante):
//   1) força parecer.especialista = área da variante;
//   2) piso: status nunca abaixo de leitura.guardrail.por_especialista[área];
//   3) meta: modelo, latência, chamadas de tool e checagem anti-alucinação.
const ctx = $('Validar Entrada').first().json;
const AREA = ctx.area;
const leitura = ctx.leitura;
const ORDEM = ['NORMAL', 'ATENCAO', 'CRITICO'];
const saidaAgente = $input.first().json;

// Tentativas do agente: cada falha de rate limit passou por "Classificar Erro" (que grava
// tentativa = nº de tentativas já feitas); a bem-sucedida é a seguinte.
let tentativas = 1;
try {
  const ult = $('Classificar Erro').last();
  if (ult && ult.json && Number.isFinite(ult.json.tentativa)) tentativas = ult.json.tentativa + 1;
} catch (x) { /* nó não executou: 1ª tentativa deu certo */ }

function tentaJson(v) {
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (x) { return v; }
}
// O agente devolve { output: {...parecer...}, intermediateSteps: [...] }.
let parecer = tentaJson(saidaAgente.output);
if (!parecer || typeof parecer !== 'object' || Array.isArray(parecer)) {
  return [{ json: { via_webhook: ctx.via_webhook, saida: {
    area: AREA, parecer: null,
    meta: { modelo: ($env.GROQ_MODEL_ENERGIA || $env.GROQ_MODEL_ESPECIALISTA || null), latencia_ms: Date.now() - ctx.t0, tool_calls: [], valores_nao_rastreaveis: [], piso_aplicado: false, tentativas, erro: 'saída do agente sem parecer estruturado' },
  } } }];
}
parecer = JSON.parse(JSON.stringify(parecer));

// 1) especialista forçado
parecer.especialista = AREA;

// 2) piso do guardrail
const piso = leitura.guardrail.por_especialista[AREA];
let piso_aplicado = false;
if (ORDEM.indexOf(parecer.status) < ORDEM.indexOf(piso)) {
  parecer.status = piso;
  piso_aplicado = true;
}

// 3a) chamadas de tool (de intermediateSteps)
const passos = Array.isArray(saidaAgente.intermediateSteps) ? saidaAgente.intermediateSteps : [];
const tool_calls = [];
const permitidos = []; // números rastreáveis

function coletar(obj) {
  if (typeof obj === 'number' && Number.isFinite(obj)) { permitidos.push(obj); return; }
  if (Array.isArray(obj)) { obj.forEach(coletar); return; }
  if (obj && typeof obj === 'object') Object.values(obj).forEach(coletar);
}

for (const p of passos) {
  const a = (p && p.action) || {};
  const nome = a.tool || a.name || null;
  // Via MCP Client o nome chega prefixado com o nó: MCP_Client_CP5_consultar_historico.
  if (!nome || !/(^|_)consultar_historico$/.test(nome)) continue;
  let entrada = tentaJson(a.toolInput);
  if (entrada && typeof entrada === 'object' && entrada.input !== undefined && Object.keys(entrada).length === 1) entrada = tentaJson(entrada.input);
  let obs = tentaJson(p.observation);
  // O agente entrega a resposta da tool como string JSON de uma LISTA de itens ([{...}]).
  if (Array.isArray(obs) && obs.length === 1) obs = obs[0];
  if (obs && typeof obs === 'object' && !Array.isArray(obs) && obs.json && typeof obs.json === 'object' && Object.keys(obs).length === 1) obs = obs.json;
  if (obs && typeof obs === 'object' && !Array.isArray(obs) && obs.response !== undefined && Object.keys(obs).length === 1) obs = tentaJson(obs.response);
  // Via MCP a resposta vem no formato de conteúdo do protocolo, [{type:'text', text:'[{...}]'}]:
  // junta os textos, parseia e desembrulha a lista de itens do n8n de novo.
  if (Array.isArray(obs) && obs.length && obs.every((x) => x && x.type === 'text' && typeof x.text === 'string')) {
    obs = tentaJson(obs.map((x) => x.text).join(''));
    if (Array.isArray(obs) && obs.length === 1) obs = obs[0];
    if (obs && typeof obs === 'object' && !Array.isArray(obs) && obs.json && typeof obs.json === 'object' && Object.keys(obs).length === 1) obs = obs.json;
  }
  const chamada = {
    tool: nome,
    entrada: (entrada && typeof entrada === 'object') ? {
      id_maquina: entrada.id_maquina ?? null, grandeza: entrada.grandeza ?? null, janela_min: entrada.janela_min ?? null,
    } : { bruto: String(entrada).slice(0, 200) },
  };
  if (obs && typeof obs === 'object') {
    chamada.saida = {
      ok: obs.ok ?? null, amostras: obs.amostras ?? null, media: obs.media ?? null, desvio_padrao: obs.desvio_padrao ?? null,
      minimo: obs.minimo ?? null, maximo: obs.maximo ?? null, primeiro: obs.primeiro ?? null, ultimo: obs.ultimo ?? null,
      variacao_percentual: obs.variacao_percentual ?? null, tendencia: obs.tendencia ?? null,
      suficiente_para_tendencia: obs.suficiente_para_tendencia ?? null,
    };
    if (obs.ok === false) chamada.saida.erro = obs.erro ?? null;
  } else {
    chamada.saida = { bruto: String(obs).slice(0, 300) };
  }
  tool_calls.push(chamada);
  coletar(entrada);
  coletar(obs);
}

// 3b) anti-alucinação: números citados que não existem na leitura, nominais, limites ou tools
coletar(leitura.valores);
coletar(leitura.nominais);
const viol = (leitura.guardrail && Array.isArray(leitura.guardrail.violacoes)) ? leitura.guardrail.violacoes : [];
for (const v of viol) { coletar(v.limite); coletar(v.valor); }

const rastreavel = (x) => permitidos.some((n) => Math.abs(n - x) <= 0.0100001);
const valores_nao_rastreaveis = [];
const achados = Array.isArray(parecer.achados) ? parecer.achados : [];
achados.forEach((a, i) => {
  if (a && typeof a.valor === 'number' && !rastreavel(a.valor)) valores_nao_rastreaveis.push({ campo: 'achados[' + i + '].valor', valor: a.valor });
});
if (parecer.tendencia && typeof parecer.tendencia === 'object') {
  for (const [k, v] of Object.entries(parecer.tendencia)) {
    if (typeof v === 'number' && !rastreavel(v)) valores_nao_rastreaveis.push({ campo: 'tendencia.' + k, valor: v });
  }
}

const meta = {
  modelo: ($env.GROQ_MODEL_ENERGIA || $env.GROQ_MODEL_ESPECIALISTA || null),
  latencia_ms: Date.now() - ctx.t0,
  tool_calls,
  valores_nao_rastreaveis,
  piso_aplicado,
  tentativas,
  erro: null,
};
return [{ json: { via_webhook: ctx.via_webhook, saida: { area: AREA, parecer, meta } } }];

// Ramo final de falha do agente (erro não recuperável, ou rate limit persistente após 3 tentativas).
// O pipeline nunca trava por causa de um especialista: devolve parecer:null + meta.erro + meta.tentativas.
const ctx = $('Validar Entrada').first().json;
const c = $input.first().json;
return [{ json: { via_webhook: ctx.via_webhook, saida: {
  area: ctx.area,
  parecer: null,
  meta: { modelo: ($env.GROQ_MODEL_ENERGIA || $env.GROQ_MODEL_ESPECIALISTA || null), latencia_ms: Date.now() - ctx.t0, tool_calls: [], valores_nao_rastreaveis: [], piso_aplicado: false, tentativas: c.tentativa, erro: c.erro_msg },
} } }];

// Entrada inválida: o LLM NÃO foi chamado. Devolve erro estruturado no mesmo shape da saída normal.
const e = $input.first().json;
return [{ json: { via_webhook: e.via_webhook, saida: {
  area: e.area,
  parecer: null,
  meta: { modelo: ($env.GROQ_MODEL_ENERGIA || $env.GROQ_MODEL_ESPECIALISTA || null), latencia_ms: Date.now() - e.t0, tool_calls: [], valores_nao_rastreaveis: [], piso_aplicado: false, tentativas: 0, erro: e.erro },
} } }];

// Caminho real (toolWorkflow / Execute Workflow): sem nó de Webhook na execução.
// Retorno COMPACTO para poupar tokens do supervisor: sem tool_calls nem latência.
// (O Webhook de teste devolve o meta completo; o smoke depende dele.)
const s = $input.first().json.saida;
const m = s.meta || {};
return [{ json: {
  area: s.area,
  parecer: s.parecer,
  meta: {
    modelo: m.modelo ?? null,
    piso_aplicado: m.piso_aplicado ?? false,
    erro: m.erro ?? null,
    tentativas: m.tentativas ?? null,
    valores_nao_rastreaveis: m.valores_nao_rastreaveis ?? [],
  },
} }];

// Classifica o erro do agente. Rate limit (429 / "too many requests" / "rate limit" / TPM) com menos
// de 3 tentativas => retentar depois de esperar (o "try again in Xs" da mensagem, entre 10 e 60 s;
// sem sugestão, 30 s). Qualquer outro erro, ou a 3ª tentativa, segue para o erro estruturado.
// $runIndex = nº de vezes que ESTE nó já rodou nesta execução = falhas anteriores do agente.
const MAX_TENTATIVAS = 3;
const bruto = $input.first().json;
const err = bruto && bruto.error !== undefined ? bruto.error : bruto;
let msg = err;
if (msg && typeof msg === 'object') msg = msg.message || msg.description || JSON.stringify(msg);
msg = String(msg === undefined || msg === null ? 'erro desconhecido' : msg);

let detalhe = '';
try {
  if (err && typeof err === 'object') {
    detalhe = [err.message, err.description, err.cause && err.cause.message, JSON.stringify(err).slice(0, 3000)].filter(Boolean).join(' | ');
  }
} catch (x) { /* ignora */ }
const texto = msg + ' | ' + detalhe;

const ehRateLimit = /\b(429|500|502|503|504)\b|too many requests|rate.?limit|tokens per minute|requests per minute|service unavailable|overloaded|bad gateway|timed? ?out|ECONNRESET/i.test(texto);
const tentativa = $runIndex + 1;

let espera_s = 30;
const m = texto.match(/try again in\s+(?:(\d+)m)?\s*([\d.]+)\s*s\b/i);
if (m) espera_s = Math.min(60, Math.max(10, Math.ceil(Number(m[1] || 0) * 60 + Number(m[2])) + 1));

// Carrega o contexto do agente (prompt_usuario etc.): o Wait devolve ESTE item ao agente.
const ctx = $('Validar Entrada').first().json;
return [{ json: {
  ...ctx,
  retentar: ehRateLimit && tentativa < MAX_TENTATIVAS,
  rate_limit: ehRateLimit,
  tentativa,
  espera_s,
  erro_msg: msg.slice(0, 500),
} }];
